@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def edit_sim_table_reason_code_textfield(valueToSet: str) -> None:
    """Locates the main Sim Dialogs window > clears the existing text in the Reason Code field and enters the specified text
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window():
       CommonActions.left_click_object_no_move(SimDialogsObjects.sim_Table_Reason_Code_Field)
       CommonActions.press_key_sequence_ctrl_a()
       CommonActions.press_delete_key()
       CommonActions.type_in_textfield(SimDialogsObjects.sim_Table_Reason_Code_Field, valueToSet)

@deco.set_separate_app_context(application_name=SIMDIALOGS_APP_NAME)
def get_sim_table_current_position_x_textfield() -> str:
    """Locates the main Sim Dialogs window > then reads the data in the Current Position X field only if the object exists
    """
    if SimDialogMainFuncs.find_main_sim_dialogs_window():
        text_value = CommonActions.get_uneditable_field_objects_text_value(SimDialogsObjects.sim_Table_Current_Pos_X_Field)
        if text_value is not None:
            return text_value
    return ""

